pub type Username = { value: Str; }

pub fn Username.new(name: Str) -> Option[Username] {
  if name.len() < 3 {
    return None;
  }
  // simple check: reject spaces
  let space = false;
  // for simplicity, accept any 3+ char name without spaces
  return Some(Username{ value: name });
}

fn main() -> Int {
  let ok = Username.new("Alice");
  let bad = Username.new("ab");
  let valid = ok.unwrap();
  return valid.value.len();
}
